import Foundation
import XCTest

/// Loads the shared contract fixtures (build plan §8.5).
///
/// The JSON in `contracts/fixtures/` is generated by the backend and copied
/// into the test bundle by a build phase, so these tests decode exactly what
/// the backend produces — without needing a running backend or a database.
///
/// A fixture that will not decode is a **build failure on purpose**: it means
/// the API changed and the Swift models did not.
enum FixtureLoader {

    enum Failure: Error, CustomStringConvertible {
        case missing(String)

        var description: String {
            switch self {
            case .missing(let name):
                return """
                    Fixture "\(name).json" is not in the test bundle.
                    Run `make contracts` to generate it, then `make ios-gen`.
                    """
            }
        }
    }

    /// `contracts/fixtures` is bundled as a folder reference, so its on-disk
    /// name is preserved. Checked case-insensitively, then flat, so the lookup
    /// survives a rename of the folder.
    private static let searchPaths: [String?] = ["fixtures", "Fixtures", nil]

    /// Raw bytes of `contracts/fixtures/<name>.json`.
    static func data(_ name: String) throws -> Data {
        let bundle = Bundle(for: BundleToken.self)

        for subdirectory in searchPaths {
            if let url = bundle.url(
                forResource: name, withExtension: "json", subdirectory: subdirectory
            ) {
                return try Data(contentsOf: url)
            }
        }
        throw Failure.missing(name)
    }

    /// Decode `contracts/fixtures/<name>.json` as `T`.
    static func decode<T: Decodable>(_ type: T.Type, from name: String) throws -> T {
        try JSONDecoder().decode(type, from: try data(name))
    }

    /// Every fixture name present in the bundle.
    ///
    /// Used to assert the folder is not silently empty — a copy phase that
    /// stopped working would otherwise make every contract test vacuously pass.
    static func allFixtureNames() -> [String] {
        let bundle = Bundle(for: BundleToken.self)
        for subdirectory in searchPaths {
            let urls =
                bundle.urls(forResourcesWithExtension: "json", subdirectory: subdirectory) ?? []
            if !urls.isEmpty {
                return urls.map { $0.deletingPathExtension().lastPathComponent }.sorted()
            }
        }
        return []
    }
}

/// Anchors `Bundle(for:)` to the test bundle.
private final class BundleToken {}
